// Elaborado por: Jorge Valencia. Entradas sintéticas, no consumo real.
const cfg={timeout_ms:120000,max_llamadas:6,tope_usd_caso:0.10,tarifa_entrada:1.25,tarifa_salida:10,tarifa_cache:0.125,moneda:'USD',fecha_tarifa:'2026-11-01',url_tarifa:'https://developers.openai.com/api/docs/models/gpt-5',version_tarifas:'ensayo-P09'};
function escenario(nombre,tope,filas,esperado,motivo){
const caso='ENSAYO-P09-'+nombre;
return {json:{autor:'Jorge Valencia',escenario:nombre,datos_sinteticos:true,esperado,motivo_esperado:motivo,
estado:{config:{...cfg,tope_usd_caso:tope},llamada_actual:{llamada_id:caso+'-NUEVA',caso_id:caso,etapa:'recepcion',agente:'Agente 1 - Recepción',tipo:'especialista',grupo_costo:'prueba_aislada',ejecucion_principal:'ensayo',inicio_ms_caso:Date.now(),body:{model:'gpt-5',max_output_tokens:1500,service_tier:'default',reasoning:{effort:'minimal'}}}},
preparacion:{errores_solicitud:[]},conteo_sintetico:{statusCode:200,body:{input_tokens:1000}},costos_sinteticos:filas}};
}
const previas=Array.from({length:6},(_,i)=>({llamada_id:'ENSAYO-PREVIA-'+(i+1),tipo_registro:'generacion',estado_conciliacion:'calculado',costo_usd:0.001}));
return [escenario('PRESUPUESTO',0.001,[],false,'Presupuesto insuficiente'),escenario('LLAMADAS',0.10,previas,false,'MAX_LLAMADAS alcanzado'),escenario('DENTRO_DE_LIMITES',0.10,[],true,null)];

// Elaborado por: Jorge Valencia.
// El cuerpo de ejecutarControl se conserva literalmente desde el export.
// Solo se sustituyen los adaptadores de entrada n8n por fixtures explícitos.
const ejecucionPrueba=$execution.id;
function ejecutarControl(fixture){
const $execution={id:ejecucionPrueba};
const $input={all:()=>fixture.costos_sinteticos.map(json=>({json}))};
const $=(nombre)=>({first:()=>({json:nombre==='Recibir llamada'?fixture.estado:nombre==='Preparar conteo'?fixture.preparacion:nombre==='Contar tokens de entrada'?fixture.conteo_sintetico:(()=>{throw new Error('Dependencia inesperada: '+nombre)})()})});
// RH-LIB v2 (2026-11-01) — funciones puras compartidas. Sin red, sin secretos.
const RH = (function () {
  const esNum = (v) => typeof v === 'number' && Number.isFinite(v);
  const esEnteroNoNeg = (v) => esNum(v) && v >= 0 && Math.floor(v) === v;
  const esListaTxt = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
  const unicos = (a) => Array.from(new Set(a));

  // Lee usage de Responses API sin sustituir ausencias por cero.
  function leerUsage(usage) {
    const r = { tokens_entrada: null, tokens_cache: null, tokens_salida: null, tokens_razonamiento: null, cache_informada: false, razonamiento_informado: false, usage_presente: false, errores: [] };
    if (!usage || typeof usage !== 'object') { r.errores.push('usage ausente'); return r; }
    r.usage_presente = true;
    if (esEnteroNoNeg(usage.input_tokens)) r.tokens_entrada = usage.input_tokens; else r.errores.push('usage.input_tokens ausente o inválido');
    if (esEnteroNoNeg(usage.output_tokens)) r.tokens_salida = usage.output_tokens; else r.errores.push('usage.output_tokens ausente o inválido');
    const det = usage.input_tokens_details;
    if (det && det.cached_tokens !== undefined && det.cached_tokens !== null) {
      if (!esEnteroNoNeg(det.cached_tokens)) r.errores.push('cached_tokens inválido (' + String(det.cached_tokens) + ')');
      else {
        r.tokens_cache = det.cached_tokens; r.cache_informada = true;
        if (r.tokens_entrada !== null && det.cached_tokens > r.tokens_entrada) r.errores.push('Incoherente: cached_tokens (' + det.cached_tokens + ') > input_tokens (' + r.tokens_entrada + ')');
      }
    }
    const od = usage.output_tokens_details;
    if (od && od.reasoning_tokens !== undefined && od.reasoning_tokens !== null) {
      if (!esEnteroNoNeg(od.reasoning_tokens)) r.errores.push('reasoning_tokens inválido');
      else {
        r.tokens_razonamiento = od.reasoning_tokens; r.razonamiento_informado = true;
        if (r.tokens_salida !== null && od.reasoning_tokens > r.tokens_salida) r.errores.push('Incoherente: reasoning_tokens > output_tokens');
      }
    }
    return r;
  }

  // costo_tokens_usd = ((in - cache) * t_in + cache * t_cache + out * t_out) / 1e6
  // El razonamiento ya está dentro de output_tokens: no se suma otra vez.
  function costoTokens(u, t) {
    if (!t || !(t.entrada > 0) || !(t.salida > 0) || !(t.cache >= 0)) return { costo: null, tipo: 'desconocido', motivo: 'Tarifas incompletas: costo no calculado.' };
    if (u.errores.length || u.tokens_entrada === null || u.tokens_salida === null) return { costo: null, tipo: 'desconocido', motivo: 'Consumo desconocido o incoherente: ' + (u.errores.join('; ') || 'usage incompleto') + '. No se presume costo cero.' };
    const cache = u.cache_informada ? u.tokens_cache : 0;
    const costo = ((u.tokens_entrada - cache) * t.entrada + cache * t.cache + u.tokens_salida * t.salida) / 1000000;
    if (u.cache_informada) return { costo: costo, tipo: 'calculado', motivo: 'Tokens medidos por usage de la API; costo calculado con tarifas configuradas. No es factura conciliada.' };
    return { costo: costo, tipo: 'estimado', motivo: 'Caché no informada por la API: estimación conservadora sin descuento de caché (no se afirma caché medida = 0). No es factura conciliada.' };
  }

  // Reserva previa: entrada contada a tarifa normal (sin presumir caché) + salida máxima permitida.
  function reservaLlamada(p) {
    const tokens = (p.tokens_conteo * p.t.entrada + p.max_salida * p.t.salida) / 1000000;
    const herramienta = (p.busquedas_max || 0) * (p.cargo_busqueda || 0);
    const contenido = (p.tokens_contenido_supuesto || 0) * p.t.entrada / 1000000;
    return { tokens: tokens, herramienta: herramienta, contenido: contenido, total: tokens + herramienta + contenido };
  }

  // Estado del presupuesto del caso a partir de las filas originales de rh_costos.
  function estadoPresupuesto(filas) {
    const gen = (filas || []).filter((f) => f && f.tipo_registro === 'generacion');
    let contabilizado = 0; let pendiente = 0; let sinCota = 0;
    gen.forEach((f) => {
      const ec = String(f.estado_conciliacion || '');
      if ((ec === 'calculado' || ec === 'estimado' || ec === 'conciliado') && esNum(f.costo_usd)) contabilizado += f.costo_usd;
      else if (esNum(f.costo_reservado_usd)) pendiente += f.costo_reservado_usd;
      else sinCota += 1;
    });
    return { intentos: gen.length, contabilizado: contabilizado, pendiente: pendiente, sin_cota: sinCota };
  }

  function evaluarAutorizacion(est, reserva, cfg) {
    const motivos = [];
    if (cfg.max_llamadas > 0 && est.intentos + 1 > cfg.max_llamadas) motivos.push('MAX_LLAMADAS alcanzado (' + est.intentos + ' intentos de generación de ' + cfg.max_llamadas + ')');
    if (est.sin_cota > 0) motivos.push(est.sin_cota + ' llamada(s) previa(s) con consumo desconocido y sin reserva cuantificada');
    if (!(cfg.tope_usd_caso > 0)) motivos.push('TOPE_USD_CASO no configurado (vacío no es ilimitado)');
    if (reserva === null) motivos.push('Sin reserva calculable');
    else {
      const total = est.contabilizado + est.pendiente + reserva.total;
      if (total > cfg.tope_usd_caso) motivos.push('Presupuesto insuficiente: contabilizado ' + est.contabilizado + ' + reservas pendientes ' + est.pendiente + ' + nueva reserva ' + reserva.total + ' = ' + total + ' USD > TOPE_USD_CASO ' + cfg.tope_usd_caso);
    }
    return motivos;
  }

  function mensajeErrorApi(status, body, modelo, fase) {
    const e = (body && body.error) || {};
    const msg = String(e.message || (typeof body === 'string' ? body : '') || '').slice(0, 300);
    const code = String(e.code || '');
    if (status === 404 || code === 'model_not_found' || /model/i.test(msg) && /(not exist|not found|does not have access|no access)/i.test(msg)) {
      return 'El modelo ' + modelo + ' no está disponible para la credencial o cuenta (' + fase + ', HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg + '. No se sustituye por otro modelo.';
    }
    return 'Error de API en ' + fase + ' (HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg;
  }

  // Extrae el texto final de una respuesta; solo 'completed' libera contenido.
  function extraerTexto(resp) {
    const r = { status: resp && resp.status ? String(resp.status) : null, texto: null, motivo: '' };
    if (!resp || typeof resp !== 'object') { r.motivo = 'Respuesta vacía'; return r; }
    if (r.status !== 'completed') {
      const det = resp.incomplete_details && resp.incomplete_details.reason ? ' (' + resp.incomplete_details.reason + ')' : '';
      r.motivo = 'Respuesta no completada: status ' + r.status + det;
      return r;
    }
    const msgs = (Array.isArray(resp.output) ? resp.output : []).filter((o) => o && o.type === 'message');
    const partes = [];
    msgs.forEach((m) => (m.content || []).forEach((c) => { if (c && c.type === 'output_text' && typeof c.text === 'string') partes.push(c.text); }));
    if (!partes.length) { r.motivo = 'Sin texto de salida'; return r; }
    r.texto = partes.join('\n');
    return r;
  }

  function hostPermitido(u, permitidos) {
    try { const x = new URL(String(u)); const h = x.hostname.toLowerCase(); return x.protocol === 'https:' && permitidos.some((d) => h === d || h.endsWith('.' + d)); } catch (e) { return false; }
  }
  function normUrl(u) {
    try { const x = new URL(String(u)); return x.hostname.toLowerCase().replace(/^www[.]/, '') + x.pathname.replace(/[/]+$/, ''); } catch (e) { return null; }
  }

  // Evidencia de búsqueda desde los metadatos devueltos (web_search_call y anotaciones), no desde el texto.
  function extraerBusqueda(resp, permitidos) {
    const out = resp && Array.isArray(resp.output) ? resp.output : [];
    const llamadas = out.filter((o) => o && o.type === 'web_search_call');
    const sinAccion = llamadas.filter((c) => !c.action || !c.action.type).length;
    const cobrables = llamadas.filter((c) => !c.action || !c.action.type || c.action.type === 'search').length;
    const completadas = llamadas.filter((c) => c.status === 'completed').length;
    const fuentes = [];
    llamadas.forEach((c) => { const ss = c.action && Array.isArray(c.action.sources) ? c.action.sources : []; ss.forEach((s) => { if (s && s.url) fuentes.push(String(s.url)); }); });
    const anot = [];
    out.filter((o) => o && o.type === 'message').forEach((m) => (m.content || []).forEach((p) => (p.annotations || []).forEach((a) => { if (a && a.type === 'url_citation' && a.url) anot.push({ url: String(a.url), title: String(a.title || '') }); })));
    const setFuentes = new Set(fuentes.map(normUrl).filter(Boolean));
    const recuperadasPermitidas = unicos(fuentes.filter((u) => hostPermitido(u, permitidos)));
    const ajenas = unicos(fuentes.filter((u) => !hostPermitido(u, permitidos)));
    const citasVerificadas = unicos(anot.filter((a) => hostPermitido(a.url, permitidos) && setFuentes.has(normUrl(a.url))).map((a) => a.url));
    const citasNoVerificadas = unicos(anot.map((a) => a.url).filter((u) => citasVerificadas.indexOf(u) < 0));
    const mostrar = citasVerificadas.length ? citasVerificadas : recuperadasPermitidas;
    return {
      llamadas_observadas: llamadas.length,
      busquedas_cobrables: cobrables,
      llamadas_sin_accion: sinAccion,
      llamadas_completadas: completadas,
      ids: llamadas.map((c) => String(c.id || '')),
      fuentes_recuperadas: unicos(fuentes),
      fuentes_permitidas: recuperadasPermitidas,
      fuentes_ajenas: ajenas,
      citas_verificadas: citasVerificadas,
      citas_no_verificadas: citasNoVerificadas,
      mostrar: mostrar,
      verificable: completadas > 0 && recuperadasPermitidas.length > 0
    };
  }

  // validado=true exige correcciones=[]; validado=false exige al menos una corrección concreta.
  function validarRevision(o) {
    const e = [];
    if (!o || typeof o !== 'object') return ['Salida vacía'];
    if (typeof o.validado !== 'boolean') e.push('validado no es booleano');
    if (!esListaTxt(o.correcciones)) e.push('correcciones no es lista de textos');
    if (!esListaTxt(o.observaciones)) e.push('observaciones no es lista de textos');
    if (e.length) return e;
    const concretas = o.correcciones.filter((c) => c.trim().length >= 8);
    if (o.validado === true && o.correcciones.length > 0) e.push('Contradicción: validado=true con correcciones no vacías');
    if (o.validado === false && concretas.length === 0) e.push('Contradicción: validado=false sin una corrección concreta');
    return e;
  }

  // JSON siempre válido; si excede el límite guarda un resumen con indicación de truncamiento.
  function jsonSeguro(v, n) {
    const t = JSON.stringify(v === undefined ? null : v);
    if (t.length <= n) return t;
    const resumen = { truncado: true, longitud_original: t.length, resumen: t.slice(0, Math.max(0, n - 120)) };
    let r = JSON.stringify(resumen);
    while (r.length > n && resumen.resumen.length > 0) { resumen.resumen = resumen.resumen.slice(0, Math.floor(resumen.resumen.length * 0.8)); r = JSON.stringify(resumen); }
    return r;
  }

  function cuerpoConteo(body) {
    const permitidas = ['model', 'instructions', 'input', 'text', 'tools', 'tool_choice', 'reasoning', 'parallel_tool_calls'];
    const c = {};
    permitidas.forEach((k) => { if (body[k] !== undefined) c[k] = body[k]; });
    return c;
  }

  function armarLlamadaEspecialista(s, p) {
    const cfg = s.config;
    const body = {
      model: cfg.modelo,
      instructions: p.instrucciones,
      input: p.prompt,
      text: { format: { type: 'json_schema', name: p.nombre_esquema, schema: p.esquema, strict: true } },
      reasoning: { effort: cfg.reasoning_effort },
      max_output_tokens: cfg.max_output_tokens,
      store: false,
      service_tier: 'default'
    };
    return {
      llamada_id: s.caso_id + '-L' + p.numero,
      caso_id: s.caso_id,
      etapa: p.etapa,
      agente: p.agente,
      tipo: 'especialista',
      body: body,
      grupo_costo: 'operacion',
      reintento: p.reintento || 0,
      loop_id: p.loop_id || null,
      skill_id: null,
      version_propuesta: p.version_propuesta === undefined ? null : p.version_propuesta,
      ejecucion_principal: s.ejecucion_id,
      evento_id: s.evento ? s.evento.evento_id : null,
      inicio_ms_caso: s.inicio_ms,
      entrada_traza: p.entrada
    };
  }

  return { esNum, esEnteroNoNeg, esListaTxt, leerUsage, costoTokens, reservaLlamada, estadoPresupuesto, evaluarAutorizacion, mensajeErrorApi, extraerTexto, hostPermitido, extraerBusqueda, validarRevision, jsonSeguro, cuerpoConteo, armarLlamadaEspecialista };
})();

const s = $('Recibir llamada').first().json;
const L = s.llamada_actual || {};
const cfg = s.config || {};
const prep = $('Preparar conteo').first().json;
const h = $('Contar tokens de entrada').first().json || {};
const filas = $input.all().map((i) => i.json).filter((o) => o && o.llamada_id);
const motivos = (prep.errores_solicitud || []).slice();
const ejecucion_id = 'principal:' + L.ejecucion_principal + ';subflujo:' + $execution.id;
let conteo = null;
let estadoConteo;
if (h.error && h.statusCode === undefined) {
  estadoConteo = 'fallo_red_o_timeout';
  motivos.push('El conteo previo de tokens falló (' + String((h.error && h.error.message) || h.error).slice(0, 200) + '); no se genera respuesta.');
} else if (!(h.statusCode >= 200 && h.statusCode < 300)) {
  estadoConteo = 'error_api';
  motivos.push(RH.mensajeErrorApi(h.statusCode, h.body, L.body && L.body.model, 'conteo de tokens') + ' No se genera respuesta.');
} else if (!RH.esEnteroNoNeg(h.body && h.body.input_tokens)) {
  estadoConteo = 'sin_input_tokens';
  motivos.push('El conteo no devolvió input_tokens válido; no se genera respuesta.');
} else { conteo = h.body.input_tokens; estadoConteo = 'ok'; }
if (filas.some((f) => f.llamada_id === L.llamada_id)) motivos.push('llamada_id ' + L.llamada_id + ' ya existe en rh_costos; no se repite la llamada.');
const est = RH.estadoPresupuesto(filas);
const restante = cfg.timeout_ms - (Date.now() - L.inicio_ms_caso);
if (!(restante > 2000)) motivos.push('TIMEOUT_MS global agotado o insuficiente para otra solicitud.');
const esLft = L.tipo === 'lft';
const t = { entrada: cfg.tarifa_entrada, salida: cfg.tarifa_salida, cache: cfg.tarifa_cache };
if (!(t.entrada > 0) || !(t.salida > 0) || t.cache === null || !(t.cache >= 0)) motivos.push('Tarifas incompletas.');
if (esLft && !(cfg.cargo_busqueda_usd > 0)) motivos.push('CARGO_BUSQUEDA_USD pendiente.');
if (esLft && (cfg.supuesto_tokens_contenido_busqueda === null || !(cfg.supuesto_tokens_contenido_busqueda >= 0))) motivos.push('SUPUESTO_TOKENS_CONTENIDO_BUSQUEDA pendiente.');
let reserva = null;
if (conteo !== null && L.body) {
  reserva = RH.reservaLlamada({ tokens_conteo: conteo, max_salida: L.body.max_output_tokens, t: t, busquedas_max: esLft ? (L.body.max_tool_calls || 0) : 0, cargo_busqueda: esLft ? cfg.cargo_busqueda_usd : 0, tokens_contenido_supuesto: esLft ? cfg.supuesto_tokens_contenido_busqueda : 0 });
}
RH.evaluarAutorizacion(est, reserva, cfg).forEach((m) => { if (motivos.indexOf(m) < 0) motivos.push(m); });
const permitido = motivos.length === 0;
const ahora = new Date().toISOString();
const fila_conteo = {
  llamada_id: L.llamada_id + '-C', caso_id: L.caso_id, etapa: L.etapa, agente: L.agente, proveedor: 'openai', modelo: L.body ? L.body.model : null,
  fecha_hora: ahora, tipo_registro: 'conteo_auxiliar', estado: estadoConteo, estado_conciliacion: 'no_aplica', unidad_cobro: 'no aplica (solicitud auxiliar de conteo)',
  tokens_entrada_conteo: conteo, origen_dato: 'conteo_api_input_tokens', motivo_estimacion: 'Solicitud auxiliar POST /v1/responses/input_tokens; no es una llamada de generación ni cuenta en MAX_LLAMADAS. No se presume su facturación.',
  ejecucion_id: ejecucion_id, grupo_costo: L.grupo_costo || 'operacion', evidencia: RH.jsonSeguro({ http_status: h.statusCode === undefined ? null : h.statusCode }, 500), loop_id: L.loop_id || null, skill_id: L.skill_id || null
};
let motivoReserva = null;
if (reserva) {
  motivoReserva = 'Reserva previa = ' + conteo + ' tokens de entrada contados x tarifa normal (sin presumir caché) + ' + L.body.max_output_tokens + ' tokens de salida máximos x tarifa de salida = ' + reserva.tokens + ' USD';
  if (esLft) motivoReserva += '; cargo de herramienta reservado ' + reserva.herramienta + ' USD (' + L.body.max_tool_calls + ' búsqueda máx.); estimación de contenido recuperado ' + reserva.contenido + ' USD (supuesto de ' + cfg.supuesto_tokens_contenido_busqueda + ' tokens; NO es cota garantizada)';
  motivoReserva += '.';
}
const fila_reserva = permitido ? {
  llamada_id: L.llamada_id, caso_id: L.caso_id, etapa: L.etapa, agente: L.agente, proveedor: 'openai', modelo: L.body.model, fecha_hora: ahora, moneda: cfg.moneda,
  estado: 'reservada', origen_dato: 'reserva_previa', motivo_estimacion: motivoReserva,
  tokens_entrada: null, tokens_salida: null, tokens_cache: null, duracion_ms: null,
  tarifa_entrada_millon: cfg.tarifa_entrada, tarifa_salida_millon: cfg.tarifa_salida, cargo_busqueda_usd: null, costo_usd: null, reintento: L.reintento || 0,
  response_id: null, ejecucion_id: ejecucion_id, tipo_registro: 'generacion', modalidad: 'standard', unidad_cobro: esLft ? 'tokens + llamada de búsqueda web' : 'tokens',
  fecha_tarifa: cfg.fecha_tarifa, url_tarifa: cfg.url_tarifa, version_tarifas: cfg.version_tarifas, grupo_costo: L.grupo_costo || 'operacion', estado_conciliacion: 'pendiente',
  skill_id: L.skill_id || null, loop_id: L.loop_id || null, tokens_razonamiento: null, tarifa_cache_millon: cfg.tarifa_cache, costo_tokens_usd: null, cantidad_busquedas: null,
  duracion_voz_seg: null, cantidad_unidades: null, tarifa_unitaria: esLft ? cfg.cargo_busqueda_usd : null, importe_incluido_usd: null, cargo_adicional_usd: null,
  costo_reservado_usd: reserva.total, tokens_entrada_conteo: conteo, estimacion_contenido_usd: esLft ? reserva.contenido : null, evidencia: null, llamadas_ref: null
} : null;
return [{ json: { permitido: permitido, motivos: motivos, conteo: conteo, reserva: reserva, presupuesto: est, timeout_http_ms: Math.max(1000, Math.min(restante, cfg.timeout_ms)), ejecucion_id: ejecucion_id, fila_conteo: fila_conteo, fila_reserva: fila_reserva, t_control: Date.now() } }];
}
return $input.all().map(item=>{
const f=item.json;
const r=ejecutarControl(f)[0].json;
const causaOk=f.motivo_esperado===null?r.motivos.length===0:r.motivos.some(m=>m.includes(f.motivo_esperado));
const reservaOk=f.esperado?r.fila_reserva!==null:r.fila_reserva===null;
